import Foundation

public struct Choice: Codable, Equatable, Sendable, Identifiable {
    public let id: String
    public let text: String
}
public struct MatchPair: Codable, Equatable, Sendable, Identifiable {
    public let id: String
    public let left: String
    public let right: String
}
public enum QuestionKind: String, Codable, Sendable { case choice, matching, wordTiles = "word_tiles" }
public struct Question: Codable, Equatable, Sendable, Identifiable {
    public let id: String
    public let prompt: String
    public let options: [Choice]
    public let answer: String
    public let explanation: String
    public let kind: QuestionKind
    public let pairs: [MatchPair]
    public let words: [Choice]
    public let answerWords: [String]
    enum CodingKeys: String, CodingKey { case id, prompt, options, answer, explanation, kind, pairs, words; case answerWords = "answer_words" }
    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        id = try c.decode(String.self, forKey: .id)
        prompt = try c.decode(String.self, forKey: .prompt)
        explanation = try c.decode(String.self, forKey: .explanation)
        kind = try c.decodeIfPresent(QuestionKind.self, forKey: .kind) ?? .choice
        options = try c.decodeIfPresent([Choice].self, forKey: .options) ?? []
        answer = try c.decodeIfPresent(String.self, forKey: .answer) ?? ""
        pairs = try c.decodeIfPresent([MatchPair].self, forKey: .pairs) ?? []
        words = try c.decodeIfPresent([Choice].self, forKey: .words) ?? []
        answerWords = try c.decodeIfPresent([String].self, forKey: .answerWords) ?? []
    }
    public var correction: String {
        switch kind {
        case .choice: return options.first { $0.id == answer }?.text ?? ""
        case .matching: return pairs.map { "\($0.left) — \($0.right)" }.joined(separator: "; ")
        case .wordTiles: return answerWords.compactMap { id in words.first { $0.id == id }?.text }.joined(separator: " ")
        }
    }
    var valid: Bool {
        func unique(_ ids: [String]) -> Bool { !ids.isEmpty && Set(ids).count == ids.count }
        switch kind {
        case .choice: return unique(options.map(\.id)) && options.contains { $0.id == answer }
        case .matching: return unique(pairs.map(\.id))
        case .wordTiles: return unique(words.map(\.id)) && unique(answerWords) && answerWords.allSatisfy { id in words.contains { $0.id == id } }
        }
    }
}
public struct LessonDefinition: Codable, Equatable, Sendable, Identifiable {
    public let id: String
    public let title: String
    public let questions: [Question]
}
public struct Course: Codable, Equatable, Sendable, Identifiable {
    public let id: String
    public let title: String
    public let questions: [Question]
    public let lessons: [LessonDefinition]
    enum CodingKeys: String, CodingKey { case id, title, questions, lessons }
    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        id = try c.decode(String.self, forKey: .id)
        title = try c.decode(String.self, forKey: .title)
        if let definitions = try c.decodeIfPresent([LessonDefinition].self, forKey: .lessons) {
            lessons = definitions
            questions = definitions.flatMap(\.questions)
        } else {
            questions = try c.decode([Question].self, forKey: .questions)
            lessons = [LessonDefinition(id: id, title: title, questions: questions)]
        }
    }
    private init(id: String, title: String, questions: [Question]) {
        self.id = id; self.title = title; self.questions = questions
        lessons = [LessonDefinition(id: id, title: title, questions: questions)]
    }
    public func lessonCourse(at index: Int) -> Course {
        let definition = lessons[index]
        return Course(id: definition.id, title: definition.title, questions: definition.questions)
    }
    public static func readFixture(_ url: URL) throws -> Course {
        struct DataSection: Decodable { let candidate_course: Course }
        struct Fixture: Decodable { let data: DataSection }
        let course = try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url)).data.candidate_course
        guard !course.lessons.isEmpty, Set(course.lessons.map(\.id)).count == course.lessons.count,
              course.lessons.allSatisfy({ !$0.questions.isEmpty }),
              Set(course.questions.map(\.id)).count == course.questions.count,
              course.questions.allSatisfy(\.valid) else { throw CocoaError(.fileReadCorruptFile) }
        return course
    }
}

public struct Lesson: Equatable, Sendable {
    public let course: Course
    public private(set) var position = 0
    public private(set) var selected: String?
    public private(set) var feedback: Bool?
    public private(set) var hearts = 5
    public private(set) var review = [Int]()
    public private(set) var reviewing = false
    public private(set) var complete = false
    public private(set) var selectedWords = [String]()
    public private(set) var matchedPairs = Set<String>()
    public private(set) var selectedLeft: String?
    public private(set) var selectedRight: String?
    public private(set) var pairError = false
    private var matchingMistake = false
    public var question: Question { course.questions[position] }
    public var canSubmit: Bool {
        guard feedback == nil, !complete else { return false }
        switch question.kind {
        case .choice: return selected != nil
        case .wordTiles: return !selectedWords.isEmpty
        case .matching: return matchedPairs.count == question.pairs.count
        }
    }
    public init(course: Course) { self.course = course }
    public mutating func choose(_ id: String) {
        guard question.kind == .choice, feedback == nil, !complete, question.options.contains(where: { $0.id == id }) else { return }
        selected = id
    }
    public mutating func addWord(_ id: String) {
        guard question.kind == .wordTiles, feedback == nil, !complete,
              !selectedWords.contains(id), question.words.contains(where: { $0.id == id }) else { return }
        selectedWords.append(id)
    }
    public mutating func removeWord(_ id: String) {
        guard feedback == nil, !complete else { return }
        selectedWords.removeAll { $0 == id }
    }
    private mutating func registerMistake() {
        hearts = max(0, hearts - 1)
        if !review.contains(position) { review.append(position) }
    }
    public mutating func selectPair(_ id: String, left: Bool) {
        guard question.kind == .matching, feedback == nil, !complete,
              !matchedPairs.contains(id), question.pairs.contains(where: { $0.id == id }) else { return }
        pairError = false
        if left { selectedLeft = id } else { selectedRight = id }
        if let a = selectedLeft, let b = selectedRight {
            if a == b { matchedPairs.insert(a) }
            else { registerMistake(); matchingMistake = true; pairError = true }
            selectedLeft = nil; selectedRight = nil
            if matchedPairs.count == question.pairs.count { feedback = !matchingMistake }
        }
    }
    public mutating func submit() {
        guard canSubmit else { return }
        let correct: Bool
        switch question.kind {
        case .choice: correct = selected == question.answer
        case .wordTiles: correct = selectedWords == question.answerWords
        case .matching: correct = !matchingMistake
        }
        feedback = correct
        if !correct && question.kind != .matching { registerMistake() }
    }
    private mutating func clearAnswer() {
        selected = nil; feedback = nil; selectedWords = []; matchedPairs = []
        selectedLeft = nil; selectedRight = nil; pairError = false; matchingMistake = false
    }
    public mutating func advance() {
        guard feedback != nil, !complete else { return }
        if reviewing {
            if feedback == true { review.removeAll { $0 == position } }
        } else if position + 1 < course.questions.count {
            position += 1; clearAnswer(); return
        } else { reviewing = true }
        if let next = review.first { position = next }
        else { complete = true }
        clearAnswer()
    }
}

public struct LearningProgress: Codable, Equatable, Sendable {
    public var completedCourses: Set<String> = []
    public var completedLessons: Set<String> = []
    public init() {}
    enum CodingKeys: String, CodingKey { case completedCourses, completedLessons }
    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        completedCourses = try c.decode(Set<String>.self, forKey: .completedCourses)
        completedLessons = try c.decodeIfPresent(Set<String>.self, forKey: .completedLessons) ?? []
    }
    public func isComplete(_ lesson: LessonDefinition, in course: Course) -> Bool {
        completedCourses.contains(course.id) || completedLessons.contains(course.id + "/" + lesson.id)
    }
    public func canStart(_ index: Int, in course: Course) -> Bool {
        course.lessons.indices.contains(index) && course.lessons.prefix(index).allSatisfy { isComplete($0, in: course) }
    }
    public mutating func finish(_ index: Int, in course: Course) {
        guard canStart(index, in: course) else { return }
        completedLessons.insert(course.id + "/" + course.lessons[index].id)
        if course.lessons.allSatisfy({ isComplete($0, in: course) }) { completedCourses.insert(course.id) }
    }
}
public struct ProgressStore: Sendable {
    public let url: URL
    public init(url: URL) { self.url = url }
    public func load() throws -> LearningProgress {
        guard FileManager.default.fileExists(atPath: url.path) else { return LearningProgress() }
        return try JSONDecoder().decode(LearningProgress.self, from: Data(contentsOf: url))
    }
    public func save(_ progress: LearningProgress) throws {
        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
        try JSONEncoder().encode(progress).write(to: url, options: .atomic)
    }
}

