import SwiftUI
import AppKit
import Observation
import LearningCore

@MainActor @Observable final class LearningModel {
    let course: Course
    let store: ProgressStore
    var progress: LearningProgress
    var lesson: Lesson?
    var lessonIndex = 0
    var confirmingExit = false
    var error: String?
    init(course: Course, store: ProgressStore) throws {
        self.course = course; self.store = store; progress = try store.load()
    }
    var completedCount: Int { course.lessons.filter { progress.isComplete($0, in: course) }.count }
    func start(_ index: Int) {
        guard progress.canStart(index, in: course) else { return }
        lessonIndex = index; lesson = Lesson(course: course.lessonCourse(at: index)); confirmingExit = false
    }
    func advance() {
        lesson?.advance()
        if lesson?.complete == true { saveCompletion() }
    }
    func saveCompletion() {
        var updated = progress
        updated.finish(lessonIndex, in: course)
        do { try store.save(updated); progress = updated; error = nil }
        catch { self.error = "Progress could not be saved. Please try again." }
    }
    func discard() { lesson = nil; confirmingExit = false }
}

@MainActor final class AppDelegate: NSObject, NSApplicationDelegate {
    func applicationDidFinishLaunching(_ notification: Notification) {
        NSApp.setActivationPolicy(.regular); NSApp.activate(ignoringOtherApps: true)
    }
    func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool { true }
}

@main struct LingoSeedApp: App {
    @NSApplicationDelegateAdaptor(AppDelegate.self) var delegate
    @State private var model: LearningModel?
    @State private var startupError: String?
    init() {
        func argument(_ name: String) -> String? {
            guard let index = CommandLine.arguments.firstIndex(of: name), index + 1 < CommandLine.arguments.count else { return nil }
            return CommandLine.arguments[index + 1]
        }
        let fixture = URL(fileURLWithPath: argument("--fixture") ?? "projects/duolingo-web/fixture-v2.json")
        let progress = argument("--progress").map { URL(fileURLWithPath: $0) }
            ?? FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0].appendingPathComponent("LingoSeed/progress.json")
        do { _model = State(initialValue: try LearningModel(course: Course.readFixture(fixture), store: ProgressStore(url: progress))) }
        catch { _startupError = State(initialValue: "Unable to open the course or saved progress. Check the supplied files before restarting.") }
    }
    var body: some Scene {
        WindowGroup("LingoSeed") {
            if let model { LearningView(model: model) }
            else { ContentUnavailableView("Course unavailable", systemImage: "book.closed", description: Text(startupError ?? "Unknown error")) }
        }.defaultSize(width: 940, height: 760)
    }
}

struct LearningView: View {
    @Bindable var model: LearningModel
    private let ink = Color(red: 0.09, green: 0.22, blue: 0.25)
    private let accent = Color(red: 0.0, green: 0.43, blue: 0.40)
    var body: some View {
        VStack(alignment: .leading, spacing: 24) {
            HStack {
                Label("LingoSeed", systemImage: "leaf.fill").font(.title2.bold()).foregroundStyle(accent)
                Spacer()
                Text("A little practice. A new possibility.").foregroundStyle(.secondary)
            }
            Divider()
            if let lesson = model.lesson {
                HStack {
                    Button("Close lesson", systemImage: "xmark") { model.confirmingExit = true }.accessibilityIdentifier("quit")
                    Spacer()
                    Text("♥ \(lesson.hearts)").font(.title3.bold()).foregroundStyle(.pink)
                        .accessibilityIdentifier("hearts").accessibilityValue(String(lesson.hearts))
                }
                if model.confirmingExit { exitConfirmation }
                else if lesson.complete { completion }
                else { exercise(lesson) }
            } else { path }
            if let error = model.error {
                HStack {
                    Text(error).foregroundStyle(.red)
                    if model.lesson?.complete == true { Button("Retry saving") { model.saveCompletion() } }
                }
            }
        }
        .padding(36).frame(minWidth: 720, minHeight: 680)
        .foregroundStyle(ink).background(Color(red: 0.96, green: 0.97, blue: 0.94))
    }
    private var exitConfirmation: some View {
        VStack(alignment: .leading, spacing: 22) {
            Text("Leave this lesson?").font(.largeTitle.bold()).accessibilityIdentifier("exit-title")
            Text("Your finished lessons are safe. This unfinished attempt will be discarded.").foregroundStyle(.secondary)
            Button("Keep learning") { model.confirmingExit = false }.buttonStyle(.borderedProminent).tint(accent).accessibilityIdentifier("cancel-quit")
            Button("Discard attempt") { model.discard() }.accessibilityIdentifier("confirm-quit")
        }.frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .leading)
    }
    private var completion: some View {
        VStack(alignment: .leading, spacing: 20) {
            Image(systemName: "checkmark.seal.fill").font(.system(size: 64)).foregroundStyle(accent)
            Text("Lesson complete").font(.largeTitle.bold()).accessibilityIdentifier("lesson-complete")
            Text("You made time for your next step.").foregroundStyle(.secondary)
            Text(model.course.lessons[model.lessonIndex].title).font(.title2)
            Button("Back to your path") { model.discard() }.buttonStyle(.borderedProminent).tint(accent).accessibilityIdentifier("return-path")
        }.frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .leading)
    }
    private var path: some View {
        VStack(alignment: .leading, spacing: 20) {
            Text("Your learning path").font(.system(size: 38, weight: .bold)).accessibilityIdentifier("course-entry")
            Text("Build confidence, one small conversation at a time.").font(.title3).foregroundStyle(.secondary)
            HStack {
                Text(model.course.title).font(.title.bold())
                Spacer()
                Text("\(model.completedCount) of \(model.course.lessons.count) lessons complete")
                    .accessibilityIdentifier("completed-count").accessibilityValue(String(model.completedCount))
            }.foregroundStyle(accent)
            ForEach(Array(model.course.lessons.enumerated()), id: \.element.id) { index, definition in
                let finished = model.progress.isComplete(definition, in: model.course)
                let unlocked = model.progress.canStart(index, in: model.course)
                HStack(spacing: 20) {
                    Image(systemName: finished ? "checkmark.seal.fill" : unlocked ? "sun.max.fill" : "lock.fill")
                        .font(.system(size: 32)).foregroundStyle(accent)
                    VStack(alignment: .leading, spacing: 8) {
                        Text("LESSON \(index + 1)").font(.caption.bold()).foregroundStyle(.secondary)
                        Text(definition.title).font(.title2.bold())
                        Text(finished ? "Completed · Ready to practice again" : unlocked ? "\(definition.questions.count) small steps" : "Complete lesson \(index) to unlock").foregroundStyle(.secondary)
                    }
                    Spacer()
                    Button(finished ? "Practice again" : "Start lesson") { model.start(index) }
                        .buttonStyle(.borderedProminent).tint(accent).controlSize(.large)
                        .disabled(!unlocked).accessibilityIdentifier(index == 0 ? "start-lesson" : "start-lesson-\(index)")
                }.padding(24).frame(maxWidth: .infinity, alignment: .leading)
                    .background(.white, in: RoundedRectangle(cornerRadius: 22))
            }
            Spacer()
            Text("Small steps grow into everyday skills.").foregroundStyle(.secondary)
        }
    }
    private func exercise(_ lesson: Lesson) -> some View {
        VStack(alignment: .leading, spacing: 18) {
            HStack {
                if lesson.reviewing {
                    Text("ONE MORE LOOK · Review your missed questions").accessibilityIdentifier("review-label")
                } else { Text("LESSON \(model.lessonIndex + 1) · \(lesson.position + 1) / \(lesson.course.questions.count)") }
                Spacer()
                Text(model.course.lessons[model.lessonIndex].title)
            }.font(.caption.bold()).foregroundStyle(accent)
            ProgressView(value: Double(lesson.position + 1), total: Double(lesson.course.questions.count)).tint(accent)
            Text(lesson.question.prompt).font(.system(size: 30, weight: .bold))
                .accessibilityIdentifier("question-title").accessibilityValue(lesson.question.prompt)
            switch lesson.question.kind {
            case .choice: choices(lesson)
            case .matching: matching(lesson)
            case .wordTiles: words(lesson)
            }
            Spacer(minLength: 0)
            if let correct = lesson.feedback {
                VStack(alignment: .leading, spacing: 10) {
                    Text(correct ? "Correct!" : "Correct answer: \(lesson.question.correction)")
                        .font(.title3.bold()).foregroundStyle(correct ? accent : .orange)
                        .accessibilityIdentifier("feedback").accessibilityValue(correct ? "correct" : "incorrect")
                    Text(lesson.question.explanation).foregroundStyle(.secondary)
                    if !correct { Text("You'll revisit this question before finishing.").font(.callout) }
                    Button("Continue") { model.advance() }.buttonStyle(.borderedProminent).tint(accent).accessibilityIdentifier("continue")
                }.padding(18).frame(maxWidth: .infinity, alignment: .leading)
                    .background(correct ? accent.opacity(0.08) : Color.orange.opacity(0.08), in: RoundedRectangle(cornerRadius: 16))
            } else if lesson.question.kind != .matching {
                Button("Check answer") { model.lesson?.submit() }.buttonStyle(.borderedProminent).tint(accent)
                    .disabled(!lesson.canSubmit).accessibilityIdentifier("check")
            }
        }
    }
    private func choices(_ lesson: Lesson) -> some View {
        VStack(spacing: 10) {
            ForEach(lesson.question.options) { option in
                Button { model.lesson?.choose(option.id) } label: {
                    HStack {
                        Image(systemName: lesson.selected == option.id ? "checkmark.circle.fill" : "circle")
                        Text(option.text).font(.title3.weight(.medium)); Spacer()
                    }.padding(16).frame(maxWidth: .infinity)
                }.buttonStyle(.bordered).tint(lesson.selected == option.id ? accent : ink)
                    .disabled(lesson.feedback != nil).accessibilityIdentifier("option-" + option.id)
                    .accessibilityValue(lesson.selected == option.id ? "selected" : "not selected")
            }
        }
    }
    private func words(_ lesson: Lesson) -> some View {
        VStack(alignment: .leading, spacing: 18) {
            Text("Tap words in order. Tap an answer word to remove it.").foregroundStyle(.secondary)
            HStack(spacing: 10) {
                ForEach(lesson.selectedWords, id: \.self) { id in
                    Button(lesson.question.words.first { $0.id == id }?.text ?? id) { model.lesson?.removeWord(id) }
                        .buttonStyle(.borderedProminent).tint(accent).controlSize(.large)
                        .disabled(lesson.feedback != nil).accessibilityIdentifier("selected-word-" + id)
                }
                if lesson.selectedWords.isEmpty { Text("Your phrase").foregroundStyle(.secondary) }
                Spacer(minLength: 0)
            }.padding(18).frame(minHeight: 76).background(.white, in: RoundedRectangle(cornerRadius: 16))
            HStack(spacing: 10) {
                ForEach(lesson.question.words) { word in
                    Button(word.text) { model.lesson?.addWord(word.id) }.buttonStyle(.bordered).controlSize(.large)
                        .disabled(lesson.feedback != nil || lesson.selectedWords.contains(word.id))
                        .accessibilityIdentifier("word-bank-" + word.id)
                }
            }
        }
    }
    private func matching(_ lesson: Lesson) -> some View {
        VStack(alignment: .leading, spacing: 12) {
            Text("Choose one expression and its matching moment.").foregroundStyle(.secondary)
            HStack(alignment: .top, spacing: 24) {
                VStack(spacing: 10) {
                    ForEach(lesson.question.pairs) { pair in
                        pairButton(pair.left, id: pair.id, left: true, lesson: lesson)
                    }
                }
                VStack(spacing: 10) {
                    ForEach(Array(lesson.question.pairs.reversed())) { pair in
                        pairButton(pair.right, id: pair.id, left: false, lesson: lesson)
                    }
                }
            }
            if lesson.pairError { Text("Those don't match. Try another pair.").foregroundStyle(.orange).accessibilityIdentifier("pair-error") }
        }
    }
    private func pairButton(_ title: String, id: String, left: Bool, lesson: Lesson) -> some View {
        let matched = lesson.matchedPairs.contains(id)
        let selected = (left ? lesson.selectedLeft : lesson.selectedRight) == id
        return Button { model.lesson?.selectPair(id, left: left) } label: {
            HStack {
                Text(title).font(.title3)
                Spacer()
                if matched { Image(systemName: "checkmark.circle.fill") }
            }.padding(14).frame(maxWidth: .infinity)
        }.buttonStyle(.bordered).tint(selected || matched ? accent : ink)
            .disabled(matched || lesson.feedback != nil)
            .accessibilityIdentifier((left ? "pair-left-" : "pair-right-") + id)
            .accessibilityValue(matched ? "matched" : selected ? "selected" : "not selected")
    }
}
